      "content": "import datetime\nimport hashlib\nimport json\nfrom pathlib import Path\n\nROOT = Path(\"/private/tmp/phase06-forward-trial\")\nREPO = Path(\"/Users/xiejinheng/Coding/software-engineering\")\nNOW = datetime.datetime.now(datetime.UTC).isoformat()\nfixture = json.loads(\n    (\n        ROOT\n        / \"snapshots\"\n        / hashlib.sha256(\n            Path((\"/private/tmp/phase06-release-fixture.json\")).read_bytes()\n        ).hexdigest()\n    ).read_text()\n)\nworkflow = \"docs/workflows/06-release-and-change-management.md\"\n\n\ndef skill(name):\n    return f\"skills/06-release-and-change-management/{name}/SKILL.md\"\n\n\nentries = [\n    (\n        \"R01\",\n        \"release-closure\",\n        \"已结案；最终成功交付，仅限批准内部20人；原变更在该范围已交付。\",\n        (\n            \"事实满足05交接、固定候选、内部授权、实际覆盖、目标验证、30分钟与2\"\n            \"0有效会话、全部指标、文档通知及显式07接收八项。内部目标不额外要求全\"\n            \"量生产。\"\n        ),\n        \"无场景声明内缺口；真实批准及证据仅按输入模拟事实。\",\n        \"登记八项证据及结案人/时区时间，07按已接收范围持续运行。\",\n    ),\n    (\n        \"R02\",\n        \"release-candidate-preparation\",\n        \"候选包含A+B，候选就绪阻塞，不能宣称只发布A。\",\n        (\n            \"main的完整包含范围为A/B，逐项05\"\n            \"通过不证明组合新增兼容风险；无B开关隔离\"\n            \"证据时按完整影响。\"\n        ),\n        \"组合兼容验证；若只发A还缺可追溯的排除/隔离依据及其验证。\",\n        (\n            \"登记完整候选清单并补组合风险验证；或另定\"\n            \"真正仅含A的新固定候选，重验受影响范围后\"\n            \"交就绪检查。\"\n        ),\n    ),\n    (\n        \"R03\",\n        \"release-candidate-preparation\",\n        \"暂停正式分发Y。\",\n        (\"转换run与X→Y映射有用，但Y摘要不同，是实际分发对象；X预演不自动覆盖Y。\"),\n        \"Y的新候选修订/摘要绑定、签名与最终包适用验证、受影响就绪及授权重评。\",\n        (\"保留X/Y和映射，验证Y及实际分发路径，再按Y当前对象重判就绪并确认批准覆盖。\"),\n    ),\n    (\n        \"R04\",\n        \"progressive-release-execution\",\n        (\n            \"在当前就绪passed且策略仍有效、无新\"\n            \"阻塞的前提下，按策略自动执行下一授权批次\"\n            \"，无需再次询问同一批准人。\"\n        ),\n        (\n            \"低风险文案在允许类型/环境/最大范围内，\"\n            \"预批准未过期且明确授权后续批次，首批健康\"\n            \"时间与样本通过。\"\n        ),\n        \"执行前仍需核验当前现场、互斥、策略与候选未漂移；不增添重复批准。\",\n        \"记录核验与推进决定；逐批验证、观察至策略目标。仅输出决定，未实际操作。\",\n    ),\n    (\n        \"R05\",\n        \"release-readiness\",\n        (\"RC2/10%不在现有授权内，不能执行；旧授权仅曾覆盖RC1/5%及20:00–21:00+08:00窗口。\"),\n        (\"当前20:30虽在时间内，候选和比例同时越界；RC2技术通过不能替代对应人类批准。\"),\n        \"RC2/10%的有效授权及受影响就绪核对。\",\n        (\n            \"暂停拟议动作，提交RC2对象与10%范围\"\n            \"的新决定；若考虑RC1也需核对其当前就绪\"\n            \"和未撤销，不能自动转为执行。\"\n        ),\n    ),\n    (\n        \"R06\",\n        \"release-readiness\",\n        (\n            \"指定job通过后尚不能立即执行；先重新判\"\n            \"当前就绪passed，然后可按预授权自动\"\n            \"执行，无需再次确认。\"\n        ),\n        \"批准明确条件核验机制与无需再次确认，失败历史不抹除；当前最新就绪尚未重判。\",\n        \"以新job证据作出的当前就绪重判。\",\n        (\n            \"保留首次失败与重跑run、候选/制品/备\"\n            \"份目标及时间、条件核验结果、就绪重判、批\"\n            \"准来源和后续实际执行记录。\"\n        ),\n    ),\n    (\n        \"R07\",\n        \"release-readiness\",\n        \"No-Go，不能启动。\",\n        \"过期与明确撤销各自都使授权无效；技术全绿不产生授权。\",\n        \"新的有效有权人类批准。\",\n        \"保留过期及撤销记录，停止未执行动作；重新核对当前条件并取得新决定。\",\n    ),\n    (\n        \"R08\",\n        \"release-health-assessment\",\n        \"健康异常，立即停止扩大并控影响。\",\n        (\n            \"保存后再读取旧值是核心路径/数据语义失败\"\n            \"；job成功与错误率未越线不能覆盖；归因\"\n            \"未知不支持继续。\"\n        ),\n        \"影响范围、数据副作用、恢复路径适用性及实际稳定验证。\",\n        (\n            \"保全版本/配置/原始请求；按既有授权评估\"\n            \"最小恢复路径，不盲目回滚；严重或超预案转\"\n            \"07事故，明确责任及复查。\"\n        ),\n    ),\n    (\n        \"R09\",\n        \"release-health-assessment\",\n        \"继续观察，保持当前范围，不扩大。\",\n        (\"45分钟满足时间，但8/100真实会话不足；合成探测不替代事前强制真实样本。\"),\n        \"至少100个有效真实会话及全部其余指标。\",\n        (\"按事前低流量方案延长观察并补探测，保留真实/合成样本区分；不得临时下调样本门槛。\"),\n    ),\n    (\n        \"R10\",\n        \"release-health-assessment\",\n        \"无法判定，暂停推进。\",\n        (\"采集器停止15分钟、来源冲突，使无告警不可信；时间/流量达标不恢复观测有效性。\"),\n        \"数据质量、停采区间影响、冲突源对账与有效观察窗口。\",\n        (\n            \"修复采集并核对来源/延迟/范围，重新取得\"\n            \"足够当前可信证据；现场如发现硬停止则改记\"\n            \"异常处置。\"\n        ),\n    ),\n    (\n        \"R11\",\n        \"progressive-release-execution\",\n        \"阻止新配置workflow进入冲突环境，A观察期保持互斥。\",\n        (\n            \"配置影响A关键路径且无隔离；不同conc\"\n            \"urrency名字不能提供跨workfl\"\n            \"ow互斥，也不能自动取消现有发布。\"\n        ),\n        \"覆盖部署及观察期的共享协调/锁和责任人。\",\n        (\"排队新变更；完成A观察及释放条件后执行。紧急介入须先暂停A、保全现场与明确介入决定。\"),\n    ),\n    (\n        \"R12\",\n        \"progressive-release-execution\",\n        \"暂停扩大，整体结果待确认；拒绝盲目整体重试。\",\n        (\"7新/3未知是部分成功，控制端超时不代表未执行；迁移可能已提交且重试可能重复副作用。\"),\n        (\"全部10个实例实际状态/制品配置、仍运行步骤、迁移提交与外部副作用账目、混合版本兼容期限。\"),\n        (\n            \"保全首个run，核实未知3个和迁移事务；确认安全幂等/补偿/恢复或续跑\"\n            \"路径，按有效授权与现场重验新建关联执行，候选/范围变化时刷新验证批准。\"\n        ),\n    ),\n    (\n        \"R13\",\n        \"release-closure\",\n        \"取消任务只证明控制任务中断，发布状态仍待核实；不能记未执行或删除日志。\",\n        \"下游可能已拉取且实例仍运行，取消不消除落地和副作用。\",\n        (\"已完成/仍执行/未执行清单、版本范围/缓存/数据副作用和残留处理、责任接收。\"),\n        (\n            \"停止扩大并保全所有日志，对账后按授权停止分发/清理/恢复；核实残留与用\"\n            \"户影响、交接责任后可取消结案，原交付按实际事实记录。\"\n        ),\n    ),\n    (\n        \"R14\",\n        \"release-recovery-execution\",\n        \"仅代码回滚；恢复未完成，属于部分恢复，不能记失败已恢复。\",\n        (\"12条不可读且关键路径失败是剩余数据/用户影响；health200不等于恢复数据。\"),\n        \"12条记录修复/恢复授权与验证、关键路径及稳定窗口。\",\n        (\n            \"保全损坏数据证据，评估兼容数据补偿/备份恢复或已验证前滚；不擅自数据删\"\n            \"除/不可逆操作，严重或超预案转事故；复验数据不变量及真实路径后判恢复。\"\n        ),\n    ),\n    (\n        \"R15\",\n        \"release-recovery-execution\",\n        \"可评估前滚路径，当前新包未达执行门槛。\",\n        (\n            \"旧代码不兼容现有数据时盲回滚可能扩大损害\"\n            \"；新修复提交/包是新候选，旧批准不覆盖，\"\n            \"本地单测不足。\"\n        ),\n        (\n            \"新候选身份、最低适用构建/静态/目标回归\"\n            \"/数据兼容/独立证据、目标环境恢复预演、\"\n            \"当前就绪与新授权。\"\n        ),\n        (\n            \"保留旧失败并固定新包；满足正常门槛，若确有严重事件才按紧急最小通道保留\"\n            \"不可豁免项；新批准后受控前滚并验证用户/数据稳定。\"\n        ),\n    ),\n    (\n        \"R16\",\n        \"release-closure\",\n        (\"商店审核、上架、目标地区可下载已完成；批准10%实际安装目标只达1%，整体尚未成功交付结案。\"),\n        \"可获取与安装覆盖是不同事实；不能拿商店可下载替代10%安装。\",\n        \"实际安装覆盖10%及该范围目标验证、时间/有效样本健康和收口材料。\",\n        (\n            \"记录每个渠道节点及1%当前事实，在有效授\"\n            \"权内继续分阶段覆盖/观察；不临时改完成目\"\n            \"标，客户端保留兼容和前滚手段。\"\n        ),\n    ),\n    (\n        \"R17\",\n        \"release-closure\",\n        \"协同目标只部分完成；不允许删除旧接口。\",\n        (\"服务全量成功不能替代未上架客户端；60%旧客户端仍依赖兼容，首批成功不授权破坏性清理。\"),\n        (\"客户端发布/覆盖、服务客户端组合验证、旧客户端支持窗口与接口退出证据/批准。\"),\n        (\n            \"维持兼容服务，继续已批准客户端渠道并逐项\"\n            \"验证；明确旧接口清理责任、期限与支持版本\"\n            \"退出判据，满足后再按批准清理。\"\n        ),\n    ),\n    (\n        \"R18\",\n        \"emergency-change-management\",\n        \"用户影响可记已恢复；紧急变更仍未关闭。\",\n        (\n            \"最低能力、独立审查、05与文档不可豁免项\"\n            \"已按场景满足，但主线同步/完整补验未完成\"\n            \"；登记责任期限不是完成证据。\"\n        ),\n        \"主线同步、标准版本关系和完整补验的实际通过；复盘/遗留等适用关闭事项。\",\n        (\n            \"保持未关闭并按责任期限完成补验、主线和复\"\n            \"盘行动，记录实际证据后再关闭；不扩展紧急\"\n            \"功能范围。\"\n        ),\n    ),\n    (\n        \"R19\",\n        \"emergency-change-management\",\n        \"走标准流程，必需CI失败保持阻塞。\",\n        (\"周五截止及功能催促不是严重生产影响或紧迫安全事件；紧急也不能把既有必过CI失败改passed。\"),\n        \"失败CI修复与真实重验通过。\",\n        \"拒绝借紧急绕门禁，保留失败记录并修复/重验，之后再准备候选与正式批准。\",\n    ),\n    (\n        \"R20\",\n        \"release-closure\",\n        (\n            \"发布可按失败转事故结案（所述明确接收与持\"\n            \"续记录已具备）；原变更不能记成功交付，事\"\n            \"故仍开放并持续负责。\"\n        ),\n        (\n            \"发布过程结束与事故恢复责任独立；事故负责\"\n            \"人显式接收使发布责任有去向，不代表用户影\"\n            \"响已恢复。\"\n        ),\n        \"持续事故处置与最终恢复验证；发布结案其余记录按实际补齐，不能伪造成功通知。\",\n        (\n            \"记录失败转事故最终结果、实际版本/范围/用户影响及接收人时区时间；引用\"\n            \"持续恢复记录，由事故负责人继续恢复，运营不能因发布结案关闭事故。\"\n        ),\n    ),\n    (\n        \"R21\",\n        \"release-readiness\",\n        \"无需重批或重跑全部验证，保留仍有效批准与证据。\",\n        (\n            \"只补同一监控链接且已记录无影响理由，源码\"\n            \"/制品/配置/范围/条件/证据未变化，不\"\n            \"触发对象漂移。\"\n        ),\n        \"无场景内缺口；保留补充时间、变更diff与无影响理由。\",\n        \"按当前有效授权和健康条件继续；后续若相关实质变化再重评受影响范围。\",\n    ),\n    (\n        \"R22\",\n        \"progressive-release-execution\",\n        (\n            \"限定HTTP本地实测通过；完整本地渠道验\"\n            \"收因真实浏览器未执行保持阻塞；不作生产/\"\n            \"正式发布结论。\"\n        ),\n        (\n            \"真实固定提交构建ZIP，两个独立目标消费同一候选ZIP，服务/API/\"\n            \"匿名拒绝/HTML真实请求通过，受控503暂停并原旧ZIP恢复；取消后\"\n            \"核实并安全新执行，原始结果在r22-actual.json。\"\n        ),\n        (\n            \"真实浏览器五状态/键盘/截图/资源证据未\"\n            \"执行；真实商店、生产保护、远端身份、数据\"\n            \"库迁移均未覆盖。\"\n        ),\n        (\n            \"保留自包含证据与恢复脚本。若要完成本地契约的Web验收，在授权隔离浏览\"\n            \"器下补真实浏览器路径；其他渠道另取权限并补平台证据。\"\n        ),\n    ),\n]\nresults = []\nfor ident, name, decision, rationale, gaps, action in entries:\n    case = next(case for case in fixture[\"cases\"] if case[\"id\"] == ident)\n    results.append(\n        case\n        | {\n            \"decision\": decision,\n            \"rationale\": rationale,\n            \"references\": [skill(name), workflow],\n            \"gaps\": gaps,\n            \"next_action\": action,\n            \"basis\": \"R01–R21按输入模拟事实独立推导；R22实际工具证据\",\n            \"decided_at\": NOW,\n        }\n    )\nreads = [json.loads(line) for line in (ROOT / \"reads.jsonl\").read_text().splitlines()]\n# Full byte snapshots bind working rules separately from committed artifact source.\ncurrent_rules = []\nfor entry in reads:\n    path = Path(entry[\"path\"])\n    if path.is_relative_to(REPO):\n        current = hashlib.sha256(path.read_bytes()).hexdigest()\n        current_rules.append(\n            {\n                \"path\": str(path.relative_to(REPO)),\n                \"read_sha256\": entry[\"sha256\"],\n                \"final_sha256\": current,\n                \"unchanged_since_read\": current == entry[\"sha256\"],\n            }\n        )\nreport = {\n    \"record_id\": \"phase06-independent-forward-trial\",\n    \"reviewer\": \"/root/phase06_forward_trial\",\n    \"independence\": (\n        \"未参与资产编写；只接收原始场景与任务，未读作者计划/预期/其他评审或验\"\n        \"证报告；git status只记录路径元数据。\"\n    ),\n    \"created_at\": NOW,\n    \"scope\": fixture[\"scope\"],\n    \"source_version\": (\"ebe6b15cbb52f5d2f098387368148a68b3b1abbc\"),\n    \"recovery_source\": (\"27862eeceb73293f73c815d7dfd0feb793ee9ea2\"),\n    \"rule_snapshot\": current_rules,\n    \"fixture\": fixture,\n    \"cases\": results,\n    \"actual_r22\": json.loads((ROOT / \"r22-actual.json\").read_text()),\n    \"issues\": [\n        {\n            \"id\": \"FT-01\",\n            \"severity\": \"environment\",\n            \"finding\": (\n                \"系统python3实际3.15.0且缺yaml，模块启动即失败；现有.venv Python3.14.8可执行。\"\n            ),\n            \"evidence\": \"commands.jsonl，first命令stderr\",\n            \"next\": \"使用现有.venv；无依赖安装。\",\n        },\n        {\n            \"id\": \"FT-02\",\n            \"severity\": \"environment\",\n            \"finding\": (\n                \"sandbox内回环绑定被拒，首个子进程退出1；只针对回环服务申请escalation后实际成功。\"\n            ),\n            \"evidence\": (\"first-venv-execution/backend-baseline/process.log，commands.jsonl\"),\n            \"next\": \"保留首失败，不覆盖。\",\n        },\n        {\n            \"id\": \"FT-03\",\n            \"severity\": \"coverage\",\n            \"finding\": (\n                \"不传browser-script时exercise输出restored\"\n                \"/exit0，然而本地契约要求Web候选与恢复的真实浏览器。调用者若把\"\n                \"restored当完整本地契约通过会误判。\"\n            ),\n            \"evidence\": (\n                \"scripts/local_delivery.py::exercise\"\n                \"/main；local-execution/exercise.json\"\n                \" 无browser字段；docs/local-delivery-cha\"\n                \"nnel.md::健康、失败与恢复\"\n            ),\n            \"next\": (\n                \"本报告将HTTP子范围通过与完整本地验收阻塞分开；可考虑CLI输出显式\"\n                \"browser-not-run/限定范围，或要求完整模式传browse\"\n                \"r-script。\"\n            ),\n        },\n        {\n            \"id\": \"FT-04\",\n            \"severity\": \"limitation\",