      "content": "\"\"\"Embed every retained evidence file; bundle and its hash are excluded from self-reference.\"\"\"\n\nimport base64\nimport datetime\nimport hashlib\nimport json\nfrom pathlib import Path\n\nROOT = Path(__file__).resolve().parent\nEXCLUDED = {\"manifest.json\", \"evidence-bundle.json\", \"evidence-bundle.sha256\"}\n\n\ndef main() -> None:\n    files = []\n    for path in sorted(ROOT.rglob(\"*\")):\n        if not path.is_file() or path.name in EXCLUDED or \"__pycache__\" in path.parts:\n            continue\n        data = path.read_bytes()\n        try:\n            content = data.decode(\"utf-8\")\n            encoding = \"utf-8\"\n        except UnicodeDecodeError:\n            content = base64.b64encode(data).decode(\"ascii\")\n            encoding = \"base64\"\n        files.append(\n            {\n                \"path\": str(path.relative_to(ROOT)),\n                \"size\": len(data),\n                \"sha256\": hashlib.sha256(data).hexdigest(),\n                \"encoding\": encoding,\n                \"content\": content,\n            }\n        )\n    manifest = {\n        \"created_at\": datetime.datetime.now(datetime.UTC).isoformat(),\n        \"scope\": \"all regular evidence files; excludes bundle/manifest/hash self-reference\",\n        \"excluded\": sorted(EXCLUDED),\n        \"files\": [{k: value for k, value in entry.items() if k != \"content\"} for entry in files],\n    }\n    (ROOT / \"manifest.json\").write_text(json.dumps(manifest, ensure_ascii=False, indent=2))\n    bundle = {\"manifest\": manifest, \"files\": files}\n    target = ROOT / \"evidence-bundle.json\"\n    target.write_text(json.dumps(bundle, ensure_ascii=False, indent=2))\n    digest = hashlib.sha256(target.read_bytes()).hexdigest()\n    (ROOT / \"evidence-bundle.sha256\").write_text(digest + \"  evidence-bundle.json\\n\")\n    for entry in files:\n        data = (\n            entry[\"content\"].encode()\n            if entry[\"encoding\"] == \"utf-8\"\n            else base64.b64decode(entry[\"content\"])\n        )\n        if hashlib.sha256(data).hexdigest() != entry[\"sha256\"]:\n            raise ValueError(\"embedded content mismatch: \" + entry[\"path\"])\n    print(\n        json.dumps(\n            {\n                \"files\": len(files),\n                \"bytes\": target.stat().st_size,\n                \"sha256\": digest,\n                \"all_embedded_digests_valid\": True,\n            }\n        )\n    )\n\n\nif __name__ == \"__main__\":\n    main()\n"
