      "encoding": "utf-8",
      "content": "<!doctype html>\n<html lang=\"en\">\n<meta charset=\"utf-8\"><meta name=\"viewport\" content=\"width=device-width, initial-scale=1\">\n<title>Domain reference</title>\n<style>body{font:18px system-ui;max-width:42rem;margin:3rem auto;padding:1rem;color:#17202a;background:#fff}button,input{font:inherit;margin:.5rem;padding:.5rem}button:focus-visible,input:focus-visible{outline:3px solid #1456b8;outline-offset:3px}#result{padding:1rem;border:1px solid #17202a;min-height:3rem}</style>\n<h1>Domain reference</h1>\n<p>Synthetic loopback fixture. Reference actors are not production authentication.</p>\n<fieldset role=\"radiogroup\" aria-label=\"Scenario\">\n<legend>Scenario</legend>\n<label><input id=\"scenario-normal\" type=\"radio\" name=\"scenario\" value=\"normal\" checked> Normal</label><br>\n<label><input id=\"scenario-fault\" type=\"radio\" name=\"scenario\" value=\"fault\"> Service failure</label><br>\n<label><input id=\"scenario-expired\" type=\"radio\" name=\"scenario\" value=\"expired\"> Expired session</label><br>\n<label><input id=\"scenario-empty\" type=\"radio\" name=\"scenario\" value=\"empty\"> Empty</label>\n</fieldset>\n<button id=\"load\">Load item</button>\n<div id=\"result\" role=\"status\" aria-live=\"polite\">Ready</div>\n<script>\nconst result = document.querySelector('#result');\nconst button = document.querySelector('#load');\nbutton.addEventListener('click', async () => {\n  const restoreFocus = document.activeElement === button;\n  button.disabled = true;\n  result.textContent = 'Loading';\n  const started = performance.now();\n  const mode = document.querySelector('input[name=scenario]:checked').value;\n  const query = mode === 'fault' ? '?fault=1' : mode === 'empty' ? '?empty=1' : '';\n  try {\n    const response = await fetch('/api/item' + query, {\n      headers: mode === 'expired' ? {} : {'X-Reference-Actor': 'actor-a'},\n      signal: AbortSignal.timeout(2000)\n    });\n    const body = await response.json();\n    result.textContent = response.ok ? body.value : `Error ${response.status}: ${body.error}. Select Normal and retry.`;\n    console.info(JSON.stringify({scenario:mode,status:response.status,elapsed_ms:performance.now()-started,body}));\n  } catch (error) {\n    result.textContent = 'Request failed. Select Normal and retry.';\n    console.error(String(error));\n  } finally {\n    button.disabled = false;\n    if (restoreFocus) button.focus();\n  }\n});\n</script>\n</html>\n"
