      "content": "\"\"\"Replay only in a new isolated directory; requires same checkout and existing venv.\"\"\"\n\nimport hashlib\nimport subprocess\nimport sys\nfrom pathlib import Path\n\nORIGINAL = Path(__file__).resolve().parent\nREPO = Path(\"/Users/xiejinheng/Coding/software-engineering\")\nEXPECTED_RUNTIME = \"d7e1a7ee4a3608c904154f001494e635491d332726dbc6f706df7dd7dd517b29\"\n\n\ndef main() -> None:\n    root = Path(sys.argv[1]).resolve()\n    if root.exists() or not str(root).startswith(\"/private/tmp/\"):\n        raise ValueError(\"a new /private/tmp directory is required\")\n    runtime = REPO / \"scripts/local_delivery.py\"\n    if hashlib.sha256(runtime.read_bytes()).hexdigest() != EXPECTED_RUNTIME:\n        raise ValueError(\"runtime changed; independently review before replay\")\n    root.mkdir()\n    command = [\n        str(REPO / \".venv/bin/python\"),\n        \"-m\",\n        \"scripts.local_delivery\",\n        \"exercise\",\n        \"--root\",\n        str(root / \"local-execution\"),\n        \"--current\",\n        \"ebe6b15cbb52f5d2f098387368148a68b3b1abbc\",\n        \"--previous\",\n        \"27862eeceb73293f73c815d7dfd0feb793ee9ea2\",\n    ]\n    result = subprocess.run(command, cwd=REPO, capture_output=True, text=True, timeout=30)\n    (root / \"first.stdout\").write_text(result.stdout)\n    (root / \"first.stderr\").write_text(result.stderr)\n    result.check_returncode()\n    source = (ORIGINAL / \"continue_trial.py\").read_text()\n    source = source.replace(\"/private/tmp/phase06-forward-trial\", str(root))\n    runner = root / \"continue_trial.py\"\n    runner.write_text(source)\n    second = subprocess.run(\n        [\n            str(REPO / \".venv/bin/python\"),\n            \"-c\",\n            \"import runpy; runpy.run_path(\" + repr(str(runner)) + \", run_name='__main__')\",\n        ],\n        cwd=REPO,\n        capture_output=True,\n        text=True,\n        timeout=30,\n    )\n    (root / \"second.stdout\").write_text