"skills/04-implementation-and-self-test/language-coding-standards/references/common.md\",\n      \"read_sha256\": \"4a9d1ac227570c9acf7d97d5157482da2a91a8a671bdb2994c5d0b356cf68821\",\n      \"final_sha256\": \"4a9d1ac227570c9acf7d97d5157482da2a91a8a671bdb2994c5d0b356cf68821\",\n      \"unchanged_since_read\": true\n    },\n    {\n      \"path\": \"skills/04-implementation-and-self-test/language-coding-standards/references/python.md\",\n      \"read_sha256\": \"93a3fcaecb9393536475171d1655875f26fc0a5d1e28c43f346d4f93ae0afb67\",\n      \"final_sha256\": \"93a3fcaecb9393536475171d1655875f26fc0a5d1e28c43f346d4f93ae0afb67\",\n      \"unchanged_since_read\": true\n    },\n    {\n      \"path\": \"pyproject.toml\",\n      \"read_sha256\": \"5d04d9985e1384b21fe861d90f967f97bf503d933bd57d89001cd2f67a73f8aa\",\n      \"final_sha256\": \"5d04d9985e1384b21fe861d90f967f97bf503d933bd57d89001cd2f67a73f8aa\",\n      \"unchanged_since_read\": true\n    },\n    {\n      \"path\": \"templates/documentation/delivery-check.md\",\n      \"read_sha256\": \"0a781b6c69da7ace605481aafe0d29bd752bf60a00b8a2deb2adb18bef97b3e9\",\n      \"final_sha256\": \"0a781b6c69da7ace605481aafe0d29bd752bf60a00b8a2deb2adb18bef97b3e9\",\n      \"unchanged_since_read\": true\n    },\n    {\n      \"path\": \"docs/quality-gates.md\",\n      \"read_sha256\": \"dca1a0c40c522ac315f298be5419a87ceb465d1454247c26d302360bee99382b\",\n      \"final_sha256\": \"dca1a0c40c522ac315f298be5419a87ceb465d1454247c26d302360bee99382b\",\n      \"unchanged_since_read\": true\n    },\n    {\n      \"path\": \"skills/06-release-and-change-management/github-release-management/SKILL.md\",\n      \"read_sha256\": \"f7cef249880b671fc8c572d62ff540e5ed68e93fe912425271611f61fd300bdf\",\n      \"final_sha256\": \"f7cef249880b671fc8c572d62ff540e5ed68e93fe912425271611f61fd300bdf\",\n      \"unchanged_since_read\": true\n    },\n    {\n      \"path\": \"tests/fixtures/domain-reference/server.py\",\n      \"read_sha256\": \"12bf5668a08a2e769c9918c7fd2461ae84c372598637624bca725d9ff661ae4b\",\n      \"final_sha256\": \"12bf5668a08a2e769c9918c7fd2461ae84c372598637624bca725d9ff661ae4b\",\n      \"unchanged_since_read\": true\n    },\n    {\n      \"path\": \"tests/fixtures/domain-reference/index.html\",\n      \"read_sha256\": \"86082c9bd44af40fbe14b37bc3693927adb31a8a06094fd0efebf7352c0a7a40\",\n      \"final_sha256\": \"86082c9bd44af40fbe14b37bc3693927adb31a8a06094fd0efebf7352c0a7a40\",\n      \"unchanged_since_read\": true\n    },\n    {\n      \"path\": \"requirements-dev.txt\",\n      \"read_sha256\": \"a1fc247ec9033cb41efc5d431cb70b4ff3022b76409329b8b5af259fe9cdf2d4\",\n      \"final_sha256\": \"a1fc247ec9033cb41efc5d431cb70b4ff3022b76409329b8b5af259fe9cdf2d4\",\n      \"unchanged_since_read\": true\n    }\n  ],\n  \"fixture\": {\n    \"schema_version\": 1,\n    \"scope\": \"phase06 independent synthetic forward use; no production authority\",\n    \"assumptions\": \"除逐案声明外不假设缺失证据通过。人物、批准、既有通过均为场景模拟事实，不认证真实人员或授权。\",\n    \"cases\": [\n      {\n        \"id\": \"R01\",\n        \"title\": \"内部渠道发布\",\n        \"facts\": \"目标只交付内部20人。候选RC1修订1固定source和制品，05交接及候选/目标环境必需验证通过；人类批准内部20人窗口，已覆盖20人，观察30分钟/至少20有效会话均满足，指标全部通过，文档通知及同人兼任07接收已记录。\",\n        \"request\": \"判断当前状态与是否可以结案。\"\n      },\n      {\n        \"id\": \"R02\",\n        \"title\": \"完整候选范围\",\n        \"facts\": \"main包含A和B，A/B各自05通过。候选包含两者，发布人说只想发A；B没有开关隔离依据。两者组合新增兼容风险尚未验证。\",\n        \"request\": \"准备候选并给出下一步。\"\n      },\n      {\n        \"id\": \"R03\",\n        \"title\": \"制品转换\",\n        \"facts\": \"预演用包X，生产签名流程生成包Y，二者摘要不同；保留转换run和输入输出，但Y尚未验证。\",\n        \"request\": \"判断是否可以继续正式分发以及缺什么证据。\"\n      },\n      {\n        \"id\": \"R04\",\n        \"title\": \"有效预批准策略\",\n        \"facts\": \"人类策略允许低风险文案，在指定环境最多全量；完整检查与自动恢复适用，候选在范围内，批准未到期。首批验证和时间/样本健康均通过，策略明确授权自动后续批次。\",\n        \"request\": \"执行者下一步需要什么决定，是否要再次询问同一批准人？只输出决定，不实际操作。\"\n      },\n      {\n        \"id\": \"R05\",\n        \"title\": \"批准漂移\",\n        \"facts\": \"RC1获准生产5%，窗口20:00至21:00+08。当前20:30，拟用RC2发布10%。RC2通过自身验证。\",\n        \"request\": \"判断现有授权可支持的动作。\"\n      },\n      {\n        \"id\": \"R06\",\n        \"title\": \"条件核验\",\n        \"facts\": \"批准人明确RC1只有备份可恢复性通过指定job后才能自动执行，无需再次确认。job之前失败，现已重跑通过；候选其余必需条件通过，最新就绪尚未重判。\",\n        \"request\": \"说明当前可执行条件及需保留记录。\"\n      },\n      {\n        \"id\": \"R07\",\n        \"title\": \"批准过期与撤销\",\n        \"facts\": \"候选未变化，批准已过期且负责人另有撤销记录。所有技术检查为绿。\",\n        \"request\": \"判断能否启动。\"\n      },\n      {\n        \"id\": \"R08\",\n        \"title\": \"操作成功但路径异常\",\n        \"facts\": \"部署job成功，实际版本正确，但真实用户保存再读取返回旧值。错误率仪表板没有越线，尚不能确定异常是否由本次变更导致。\",\n        \"request\": \"给出健康判定和立即动作。\"\n      },\n      {\n        \"id\": \"R09\",\n        \"title\": \"低流量\",\n        \"facts\": \"预设至少30分钟及100个真实会话，45分钟仅8个会话均成功，补充合成探测也通过。\",\n        \"request\": \"给出健康结论，是否扩大。\"\n      },\n      {\n        \"id\": \"R10\",\n        \"title\": \"观测异常\",\n        \"facts\": \"窗口/流量达到要求，仪表板无告警，但采集器已停止15分钟；另一个数据源有冲突结果。\",\n        \"request\": \"给出判定及动作。\"\n      },\n      {\n        \"id\": \"R11\",\n        \"title\": \"观察期并发\",\n        \"facts\": \"发布A部署完成正在观察，新workflow准备修改同环境配置；两个job concurrency名字不同。配置影响A的关键路径，无隔离依据。\",\n        \"request\": \"给出调度决定与必要控制。\"\n      },\n      {\n        \"id\": \"R12\",\n        \"title\": \"部分成功与超时\",\n        \"facts\": \"10个实例中7个显示新版本，3个状态未知。控制端超时，迁移可能已提交；维护者要求立即整体重试。\",\n        \"request\": \"说明现场核实与恢复/续跑步骤。\"\n      },\n      {\n        \"id\": \"R13\",\n        \"title\": \"取消副作用\",\n        \"facts\": \"分发任务已取消，制品可能已被下游拉取，一批实例仍运行；操作者希望把结果写成未执行并删除日志。\",\n        \"request\": \"整理实际状态和结案条件。\"\n      },\n      {\n        \"id\": \"R14\",\n        \"title\": \"回滚后的数据\",\n        \"facts\": \"旧代码已恢复，健康接口200，但新迁移造成12条记录不可读，用户关键路径仍失败。\",\n        \"request\": \"判断恢复状态和后续动作。\"\n      },\n      {\n        \"id\": \"R15\",\n        \"title\": \"前滚修复\",\n        \"facts\": \"原候选发布失败，旧代码不兼容现有数据。修复提交生成新包，只有本地单测；原批准只绑定旧候选。\",\n        \"request\": \"说明可行推进路径及当前门槛。\"\n      },\n      {\n        \"id\": \"R16\",\n        \"title\": \"商店和安装\",\n        \"facts\": \"批准目标为商店可获取并覆盖10%实际安装。审核通过且已上架，目标地区可下载正确签名包，实际安装仅1%。\",\n        \"request\": \"判断完成度与后续观察。\"\n      },\n      {\n        \"id\": \"R17\",\n        \"title\": \"多渠道及兼容退出\",\n        \"facts\": \"本次目标客户端与服务协同功能，服务全量成功，客户端未上架；旧客户端占60%。有人要求马上删除旧接口。\",\n        \"request\": \"判断交付及清理动作。\"\n      },\n      {\n        \"id\": \"R18\",\n        \"title\": \"紧急与关闭\",\n        \"facts\": \"严重事件经人类紧急授权，最小修复已有最低构建/目标测试/独立审查，05/文档等不可豁免要求已满足。用户影响恢复，但主线同步和完整补验还未完成；已登记责任与期限。\",\n        \"request\": \"分别判断恢复与紧急变更关闭。\"\n      },\n      {\n        \"id\": \"R19\",\n        \"title\": \"截止日期\",\n        \"facts\": \"普通功能赶周五发布，必需CI失败且无正在发生的严重影响，负责人说走紧急通道。\",\n        \"request\": \"选择流程和推进结论。\"\n      },\n      {\n        \"id\": \"R20\",\n        \"title\": \"事故接收\",\n        \"facts\": \"失败发布仍有用户影响，事故负责人已明确接收，关联持续恢复记录、版本范围与责任，发布团队准备结案；运营同事认为结案就可以关闭事故。\",\n        \"request\": \"说明发布结案、原变更交付和事故责任。\"\n      },\n      {\n        \"id\": \"R21\",\n        \"title\": \"文字补充\",\n        \"facts\": \"RC1批准有效，记录仅补充同一监控页面链接，源码/制品/配置/范围/条件/证据均未变，已记录无影响理由。\",\n        \"request\": \"判断是否需要重批或重跑全部验证。\"\n      },\n      {\n        \"id\": \"R22\",\n        \"title\": \"隔离本地真实执行\",\n        \"facts\": \"仅授权本机临时目录、合成数据、127.0.0.1服务和自身子进程；仓库scripts/local_delivery.py已有固定Git制品、真实服务、失败/恢复及取消能力。禁止真实远端/生产/商店/外发通知。\",\n        \"request\": \"使用阶段06技能在隔离目录实际验证固定制品、同物跨目标、目标应用路径、失败停止恢复，以及中断后的状态核实和安全新执行。保留原始产物/命令/请求/摘要/子进程收口、读资产的轨迹和可复验脚本。你自行设计实际步骤与判据，明确模拟的批准/事件与真正执行，不能把桌面决定或现有测试报告替代实际操作。\"\n      }\n    ]\n  },\n  \"cases\": [\n    {\n      \"id\": \"R01\",\n      \"title\": \"内部渠道发布\",\n      \"facts\": \"目标只交付内部20人。候选RC1修订1固定source和制品，05交接及候选/目标环境必需验证通过；人类批准内部20人窗口，已覆盖20人，观察30分钟/至少20有效会话均满足，指标全部通过，文档通知及同人兼任07接收已记录。\",\n      \"request\": \"判断当前状态与是否可以结案。\",\n      \"decision\": \"已结案；最终成功交付，仅限批准内部20人；原变更在该范围已交付。\",\n      \"rationale\": \"事实满足05交接、固定候选、内部授权、实际覆盖、目标验证、30分钟与20有效会话、全部指标、文档通知及显式07接收八项。内部目标不额外要求全量生产。\",\n      \"references\": [\n        \"skills/06-release-and-change-management/release-closure/SKILL.md\",\n        \"docs/workflows/06-release-and-change-management.md\"\n      ],\n      \"gaps\": \"无场景声明内缺口；真实批准及证据仅按输入模拟事实。\",\n      \"next_action\": \"登记八项证据及结案人/时区时间，07按已接收范围持续运行。\",\n      \"basis\": \"R01–R21按输入模拟事实独立推导；R22实际工具证据\",\n      \"decided_at\": \"2026-10-15T17:24:26.739492+00:00\"\n    },\n    {\n      \"id\": \"R02\",\n      \"title\": \"完整候选范围\",\n      \"facts\": \"main包含A和B，A/B各自05通过。候选包含两者，发布人说只想发A；B没有开关隔离依据。两者组合新增兼容风险尚未验证。\",\n      \"request\": \"准备候选并给出下一步。\",\n      \"decision\": \"候选包含A+B，候选就绪阻塞，不能宣称只发布A。\",\n      \"rationale\": \"main的完整包含范围为A/B，逐项05通过不证明组合新增兼容风险；无B开关隔离证据时按完整影响。\",\n      \"references\": [\n        \"skills/06-release-and-change-management/release-candidate-preparation/SKILL.md\",\n        \"docs/workflows/06-release-and-change-management.md\"\n      ],\n      \"gaps\": \"组合兼容验证；若只发A还缺可追溯的排除/隔离依据及其验证。\",\n      \"next_action\": \"登记完整候选清单并补组合风险验证；或另定真正仅含A的新固定候选，重验受影响范围后交就绪检查。\",\n      \"basis\": \"R01–R21按输入模拟事实独立推导；R22实际工具证据\",\n      \"decided_at\": \"2026-10-15T17:24:26.739492+00:00\"\n    },\n    {\n      \"id\": \"R03\",\n      \"title\": \"制品转换\",\n      \"facts\": \"预演用包X，生产签名流程生成包Y，二者摘要不同；保留转换run和输入输出，但Y尚未验证。\",\n      \"request\": \"判断是否可以继续正式分发以及缺什么证据。\",\n      \"decision\": \"暂停正式分发Y。\",\n      \"rationale\": \"转换run与X→Y映射有用，但Y摘要不同，是实际分发对象；X预演不自动覆盖Y。\",\n      \"references\": [\n        \"skills/06-release-and-change-management/release-candidate-preparation/SKILL.md\",\n        \"docs/workflows/06-release-and-change-management.md\"\n      ],\n      \"gaps\": \"Y的新候选修订/摘要绑定、签名与最终包适用验证、受影响就绪及授权重评。\",\n      \"next_action\": \"保留X/Y和映射，验证Y及实际分发路径，再按Y当前对象重判就绪并确认批准覆盖。\",\n      \"basis\": \"R01–R21按输入模拟事实独立推导；R22实际工具证据\",\n      \"decided_at\": \"2026-10-15T17:24:26.739492+00:00\"\n    },\n    {\n      \"id\": \"R04\",\n      \"title\": \"有效预批准策略\",\n      \"facts\": \"人类策略允许低风险文案，在指定环境最多全量；完整检查与自动恢复适用，候选在范围内，批准未到期。首批验证和时间/样本健康均通过，策略明确授权自动后续批次。\",\n      \"request\": \"执行者下一步需要什么决定，是否要再次询问同一批准人？只输出决定，不实际操作。\",\n      \"decision\": \"在当前就绪passed且策略仍有效、无新阻塞的前提下，按策略自动执行下一授权批次，无需再次询问同一批准人。\",\n      \"rationale\": \"低风险文案在允许类型/环境/最大范围内，预批准未过期且明确授权后续批次，首批健康时间与样本通过。\",\n      \"references\": [\n        \"skills/06-release-and-change-management/progressive-release-execution/SKILL.md\",\n        \"docs/workflows/06-release-and-change-management.md\"\n      ],\n      \"gaps\": \"执行前仍需核验当前现场、互斥、策略与候选未漂移；不增添重复批准。\",\n      \"next_action\": \"记录核验与推进决定；逐批验证、观察至策略目标。仅输出决定，未实际操作。\",\n      \"basis\": \"R01–R21按输入模拟事实独立推导；R22实际工具证据\",\n      \"decided_at\": \"2026-10-15T17:24:26.739492+00:00\"\n    },\n    {\n      \"id\": \"R05\",\n      \"title\": \"批准漂移\",\n      \"facts\": \"RC1获准生产5%，窗口20:00至21:00+08。当前20:30，拟用RC2发布10%。RC2通过自身验证。\",\n      \"request\": \"判断现有授权可支持的动作。\",\n      \"decision\": \"RC2/10%不在现有授权内，不能执行；旧授权仅曾覆盖RC1/5%及20:00–21:00+08:00窗口。\",\n      \"rationale\": \"当前20:30虽在时间内，候选和比例同时越界；RC2技术通过不能替代对应人类批准。\",\n      \"references\": [\n        \"skills/06-release-and-change-management/release-readiness/SKILL.md\",\n        \"docs/workflows/06-release-and-change-management.md\"\n      ],\n      \"gaps\": \"RC2/10%的有效授权及受影响就绪核对。\",\n      \"next_action\": \"暂停拟议动作，提交RC2对象与10%范围的新决定；若考虑RC1也需核对其当前就绪和未撤销，不能自动转为执行。\",\n      \"basis\": \"R01–R21按输入模拟事实独立推导；R22实际工具证据\",\n      \"decided_at\": \"2026-10-15T17:24:26.739492+00:00\"\n    },\n    {\n      \"id\": \"R06\",\n      \"title\": \"条件核验\",\n      \"facts\": \"批准人明确RC1只有备份可恢复性通过指定job后才能自动执行，无需再次确认。job之前失败，现已重跑通过；候选其余必需条件通过，最新就绪尚未重判。\",\n      \"request\": \"说明当前可执行条件及需保留记录。\",\n      \"decision\": \"指定job通过后尚不能立即执行；先重新判当前就绪passed，然后可按预授权自动执行，无需再次确认。\",\n      \"rationale\": \"批准明确条件核验机制与无需再次确认，失败历史不抹除；当前最新就绪尚未重判。\",\n      \"references\": [\n        \"skills/06-release-and-change-management/release-readiness/SKILL.md\",\n        \"docs/workflows/06-release-and-change-management.md\"\n      ],\n      \"gaps\": \"以新job证据作出的当前就绪重判。\",\n      \"next_action\": \"保留首次失败与重跑run、候选/制品/备份目标及时间、条件核验结果、就绪重判、批准来源和后续实际执行记录。\",\n      \"basis\": \"R01–R21按输入模拟事实独立推导；R22实际工具证据\",\n      \"decided_at\": \"2026-10-15T17:24:26.739492+00:00\"\n    },\n    {\n      \"id\": \"R07\",\n      \"title\": \"批准过期与撤销\",\n      \"facts\": \"候选未变化，批准已过期且负责人另有撤销记录。所有技术检查为绿。\",\n      \"request\": \"判断能否启动。\",\n      \"decision\": \"No-Go，不能启动。\",\n      \"rationale\": \"过期与明确撤销各自都使授权无效；技术全绿不产生授权。\",\n      \"references\": [\n        \"skills/06-release-and-change-management/release-readiness/SKILL.md\",\n        \"docs/workflows/06-release-and-change-management.md\"\n      ],\n      \"gaps\": \"新的有效有权人类批准。\",\n      \"next_action\": \"保留过期及撤销记录，停止未执行动作；重新核对当前条件并取得新决定。\",\n      \"basis\": \"R01–R21按输入模拟事实独立推导；R22实际工具证据\",\n      \"decided_at\": \"2026-10-15T17:24:26.739492+00:00\"\n    },\n    {\n      \"id\": \"R08\",\n      \"title\": \"操作成功但路径异常\",\n      \"facts\": \"部署job成功，实际版本正确，但真实用户保存再读取返回旧值。错误率仪表板没有越线，尚不能确定异常是否由本次变更导致。\",\n      \"request\": \"给出健康判定和立即动作。\",\n      \"decision\": \"健康异常，立即停止扩大并控影响。\",\n      \"rationale\": \"保存后再读取旧值是核心路径/数据语义失败；job成功与错误率未越线不能覆盖；归因未知不支持继续。\",\n      \"references\": [\n        \"skills/06-release-and-change-management/release-health-assessment/SKILL.md\",\n        \"docs/workflows/06-release-and-change-management.md\"\n      ],\n      \"gaps\": \"影响范围、数据副作用、恢复路径适用性及实际稳定验证。\",\n      \"next_action\": \"保全版本/配置/原始请求；按既有授权评估最小恢复路径，不盲目回滚；严重或超预案转07事故，明确责任及复查。\",\n      \"basis\": \"R01–R21按输入模拟事实独立推导；R22实际工具证据\",\n      \"decided_at\": \"2026-10-15T17:24:26.739492+00:00\"\n    },\n    {\n      \"id\": \"R09\",\n      \"title\": \"低流量\",\n      \"facts\": \"预设至少30分钟及100个真实会话，45分钟仅8个会话均成功，补充合成探测也通过。\",\n      \"request\": \"给出健康结论，是否扩大。\",\n      \"decision\": \"继续观察，保持当前范围，不扩大。\",\n      \"rationale\": \"45分钟满足时间，但8/100真实会话不足；合成探测不替代事前强制真实样本。\",\n      \"references\": [\n        \"skills/06-release-and-change-management/release-health-assessment/SKILL.md\",\n        \"docs/workflows/06-release-and-change-management.md\"\n      ],\n      \"gaps\": \"至少100个有效真实会话及全部其余指标。\",\n      \"next_action\": \"按事前低流量方案延长观察并补探测，保留真实/合成样本区分；不得临时下调样本门槛。\",\n      \"basis\": \"R01–R21按输入模拟事实独立推导；R22实际工具证据\",\n      \"decided_at\": \"2026-10-15T17:24:26.739492+00:00\"\n    },\n    {\n      \"id\": \"R10\",\n      \"title\": \"观测异常\",\n      \"facts\": \"窗口/流量达到要求，仪表板无告警，但采集器已停止15分钟；另一个数据源有冲突结果。\",\n      \"request\": \"给出判定及动作。\",\n      \"decision\": \"无法判定，暂停推进。\",\n      \"rationale\": \"采集器停止15分钟、来源冲突，使无告警不可信；时间/流量达标不恢复观测有效性。\",\n      \"references\": [\n        \"skills/06-release-and-change-management/release-health-assessment/SKILL.md\",\n        \"docs/workflows/06-release-and-change-management.md\"\n      ],\n      \"gaps\": \"数据质量、停采区间影响、冲突源对账与有效观察窗口。\",\n      \"next_action\": \"修复采集并核对来源/延迟/范围，重新取得足够当前可信证据；现场如发现硬停止则改记异常处置。\",\n      \"basis\": \"R01–R21按输入模拟事实独立推导；R22实际工具证据\",\n      \"decided_at\": \"2026-10-15T17:24:26.739492+00:00\"\n    },\n    {\n      \"id\": \"R11\",\n      \"title\": \"观察期并发\",\n      \"facts\": \"发布A部署完成正在观察，新workflow准备修改同环境配置；两个job concurrency名字不同。配置影响A的关键路径，无隔离依据。\",\n      \"request\": \"给出调度决定与必要控制。\",\n      \"decision\": \"阻止新配置workflow进入冲突环境，A观察期保持互斥。\",\n      \"rationale\": \"配置影响A关键路径且无隔离；不同concurrency名字不能提供跨workflow互斥，也不能自动取消现有发布。\",\n      \"references\": [\n        \"skills/06-release-and-change-management/progressive-release-execution/SKILL.md\",\n        \"docs/workflows/06-release-and-change-management.md\"\n      ],\n      \"gaps\": \"覆盖部署及观察期的共享协调/锁和责任人。\",\n      \"next_action\": \"排队新变更；完成A观察及释放条件后执行。紧急介入须先暂停A、保全现场与明确介入决定。\",\n      \"basis\": \"R01–R21按输入模拟事实独立推导；R22实际工具证据\",\n      \"decided_at\": \"2026-10-15T17:24:26.739492+00:00\"\n    },\n    {\n      \"id\": \"R12\",\n      \"title\": \"部分成功与超时\",\n      \"facts\": \"10个实例中7个显示新版本，3个状态未知。控制端超时，迁移可能已提交；维护者要求立即整体重试。\",\n      \"request\": \"说明现场核实与恢复/续跑步骤。\",\n      \"decision\": \"暂停扩大，整体结果待确认；拒绝盲目整体重试。\",\n      \"rationale\": \"7新/3未知是部分成功，控制端超时不代表未执行；迁移可能已提交且重试可能重复副作用。\",\n      \"references\": [\n        \"skills/06-release-and-change-management/progressive-release-execution/SKILL.md\",\n        \"docs/workflows/06-release-and-change-management.md\"\n      ],\n      \"gaps\": \"全部10个实例实际状态/制品配置、仍运行步骤、迁移提交与外部副作用账目、混合版本兼容期限。\",\n      \"next_action\": \"保全首个run，核实未知3个和迁移事务；确认安全幂等/补偿/恢复或续跑路径，按有效授权与现场重验新建关联执行，候选/范围变化时刷新验证批准。\",\n      \"basis\": \"R01–R21按输入模拟事实独立推导；R22实际工具证据\",\n      \"decided_at\": \"2026-10-15T17:24:26.739492+00:00\"\n    },\n    {\n      \"id\": \"R13\",\n      \"title\": \"取消副作用\",\n      \"facts\": \"分发任务已取消，制品可能已被下游拉取，一批实例仍运行；操作者希望把结果写成未执行并删除日志。\",\n      \"request\": \"整理实际状态和结案条件。\",\n      \"decision\": \"取消任务只证明控制任务中断，发布状态仍待核实；不能记未执行或删除日志。\",\n      \"rationale\": \"下游可能已拉取且实例仍运行，取消不消除落地和副作用。\",\n      \"references\": [\n        \"skills/06-release-and-change-management/release-closure/SKILL.md\",\n        \"docs/workflows/06-release-and-change-management.md\"\n      ],\n      \"gaps\": \"已完成/仍执行/未执行清单、版本范围/缓存/数据副作用和残留处理、责任接收。\",\n      \"next_action\": \"停止扩大并保全所有日志，对账后按授权停止分发/清理/恢复；核实残留与用户影响、交接责任后可取消结案，原交付按实际事实记录。\",\n      \"basis\": \"R01–R21按输入模拟事实独立推导；R22实际工具证据\",\n      \"decided_at\": \"2026-10-15T17:24:26.739492+00:00\"\n    },\n    {\n      \"id\": \"R14\",\n      \"title\": \"回滚后的数据\",\n      \"facts\": \"旧代码已恢复，健康接口200，但新迁移造成12条记录不可读，用户关键路径仍失败。\",\n      \"request\": \"判断恢复状态和后续动作。\",\n      \"decision\": \"仅代码回滚；恢复未完成，属于部分恢复，不能记失败已恢复。\",\n      \"rationale\": \"12条不可读且关键路径失败是剩余数据/用户影响；health200不等于恢复数据。\",\n      \"references\": [\n        \"skills/06-release-and-change-management/release-recovery-execution/SKILL.md\",\n        \"docs/workflows/06-release-and-change-management.md\"\n      ],\n      \"gaps\": \"12条记录修复/恢复授权与验证、关键路径及稳定窗口。\",\n      \"next_action\": \"保全损坏数据证据，评估兼容数据补偿/备份恢复或已验证前滚；不擅自数据删除/不可逆操作，严重或超预案转事故；复验数据不变量及真实路径后判恢复。\",\n      \"basis\": \"R01–R21按输入模拟事实独立推导；R22实际工具证据\",\n      \"decided_at\": \"2026-10-15T17:24:26.739492+00:00\"\n    },\n    {\n      \"id\": \"R15\",\n      \"title\": \"前滚修复\",\n      \"facts\": \"原候选发布失败，旧代码不兼容现有数据。修复提交生成新包，只有本地单测；原批准只绑定旧候选。\",\n      \"request\": \"说明可行推进路径及当前门槛。\",\n      \"decision\": \"可评估前滚路径，当前新包未达执行门槛。\",\n      \"rationale\": \"旧代码不兼容现有数据时盲回滚可能扩大损害；新修复提交/包是新候选，旧批准不覆盖，本地单测不足。\",\n      \"references\": [\n        \"skills/06-release-and-change-management/release-recovery-execution/SKILL.md\",\n        \"docs/workflows/06-release-and-change-management.md\"\n      ],\n      \"gaps\": \"新候选身份、最低适用构建/静态/目标回归/数据兼容/独立证据、目标环境恢复预演、当前就绪与新授权。\",\n      \"next_action\": \"保留旧失败并固定新包；满足正常门槛，若确有严重事件才按紧急最小通道保留不可豁免项；新批准后受控前滚并验证用户/数据稳定。\",\n      \"basis\": \"R01–R21按输入模拟事实独立推导；R22实际工具证据\",\n      \"decided_at\": \"2026-10-15T17:24:26.739492+00:00\"\n    },\n    {\n      \"id\": \"R16\",\n      \"title\": \"商店和安装\",\n      \"facts\": \"批准目标为商店可获取并覆盖10%实际安装。审核通过且已上架，目标地区可下载正确签名包，实际安装仅1%。\",\n      \"request\": \"判断完成度与后续观察。\",\n      \"decision\": \"商店审核、上架、目标地区可下载已完成；批准10%实际安装目标只达1%，整体尚未成功交付结案。\",\n      \"rationale\": \"可获取与安装覆盖是不同事实；不能拿商店可下载替代10%安装。\",\n      \"references\": [\n        \"skills/06-release-and-change-management/release-closure/SKILL.md\",\n        \"docs/workflows/06-release-and-change-management.md\"\n      ],\n      \"gaps\": \"实际安装覆盖10%及该范围目标验证、时间/有效样本健康和收口材料。\",\n      \"next_action\": \"记录每个渠道节点及1%当前事实，在有效授权内继续分阶段覆盖/观察；不临时改完成目标，客户端保留兼容和前滚手段。\",\n      \"basis\": \"R01–R21按输入模拟事实独立推导；R22实际工具证据\",\n      \"decided_at\": \"2026-10-15T17:24:26.739492+00:00\"\n    },\n    {\n      \"id\": \"R17\",\n      \"title\": \"多渠道及兼容退出\",\n      \"facts\": \"本次目标客户端与服务协同功能，服务全量成功，客户端未上架；旧客户端占60%。有人要求马上删除旧接口。\",\n      \"request\": \"判断交付及清理动作。\",\n      \"decision\": \"协同目标只部分完成；不允许删除旧接口。\",\n      \"rationale\": \"服务全量成功不能替代未上架客户端；60%旧客户端仍依赖兼容，首批成功不授权破坏性清理。\",\n      \"references\": [\n        \"skills/06-release-and-change-management/release-closure/SKILL.md\",\n        \"docs/workflows/06-release-and-change-management.md\"\n      ],\n      \"gaps\": \"客户端发布/覆盖、服务客户端组合验证、旧客户端支持窗口与接口退出证据/批准。\",\n      \"next_action\": \"维持兼容服务，继续已批准客户端渠道并逐项验证；明确旧接口清理责任、期限与支持版本退出判据，满足后再按批准清理。\",\n      \"basis\": \"R01–R21按输入模拟事实独立推导；R22实际工具证据\",\n      \"decided_at\": \"2026-10-15T17:24:26.739492+00:00\"\n    },\n    {\n      \"id\": \"R18\",\n      \"title\": \"紧急与关闭\",\n      \"facts\": \"严重事件经人类紧急授权，最小修复已有最低构建/目标测试/独立审查，05/文档等不可豁免要求已满足。用户影响恢复，但主线同步和完整补验还未完成；已登记责任与期限。\",\n      \"request\": \"分别判断恢复与紧急变更关闭。\",\n      \"decision\": \"用户影响可记已恢复；紧急变更仍未关闭。\",\n      \"rationale\": \"最低能力、独立审查、05与文档不可豁免项已按场景满足，但主线同步/完整补验未完成；登记责任期限不是完成证据。\",\n      \"references\": [\n        \"skills/06-release-and-change-management/emergency-change-management/SKILL.md\",\n        \"docs/workflows/06-release-and-change-management.md\"\n      ],\n      \"gaps\": \"主线同步、标准版本关系和完整补验的实际通过；复盘/遗留等适用关闭事项。\",\n      \"next_action\": \"保持未关闭并按责任期限完成补验、主线和复盘行动，记录实际证据后再关闭；不扩展紧急功能范围。\",\n      \"basis\": \"R01–R21按输入模拟事实独立推导；R22实际工具证据\",\n      \"decided_at\": \"2026-10-15T17:24:26.739492+00:00\"\n    },\n    {\n      \"id\": \"R19\",\n      \"title\": \"截止日期\",\n      \"facts\": \"普通功能赶周五发布，必需CI失败且无正在发生的严重影响，负责人说走紧急通道。\",\n      \"request\": \"选择流程和推进结论。\",\n      \"decision\": \"走标准流程，必需CI失败保持阻塞。\",\n      \"rationale\": \"周五截止及功能催促不是严重生产影响或紧迫安全事件；紧急也不能把既有必过CI失败改passed。\",\n      \"references\": [\n        \"skills/06-release-and-change-management/emergency-change-management/SKILL.md\",\n        \"docs/workflows/06-release-and-change-management.md\"\n      ],\n      \"gaps\": \"失败CI修复与真实重验通过。\",\n      \"next_action\": \"拒绝借紧急绕门禁，保留失败记录并修复/重验，之后再准备候选与正式批准。\",\n      \"basis\": \"R01–R21按输入模拟事实独立推导；R22实际工具证据\",\n      \"decided_at\": \"2026-10-15T17:24:26.739492+00:00\"\n    },\n    {\n      \"id\": \"R20\",\n      \"title\": \"事故接收\",\n      \"facts\": \"失败发布仍有用户影响，事故负责人已明确接收，关联持续恢复记录、版本范围与责任，发布团队准备结案；运营同事认为结案就可以关闭事故。\",\n      \"request\": \"说明发布结案、原变更交付和事故责任。\",\n      \"decision\": \"发布可按失败转事故结案（所述明确接收与持续记录已具备）；原变更不能记成功交付，事故仍开放并持续负责。\",\n      \"rationale\": \"发布过程结束与事故恢复责任独立；事故负责人显式接收使发布责任有去向，不代表用户影响已恢复。\",\n      \"references\": [\n        \"skills/06-release-and-change-management/release-closure/SKILL.md\",\n        \"docs/workflows/06-release-and-change-management.md\"\n      ],\n      \"gaps\": \"持续事故处置与最终恢复验证；发布结案其余记录按实际补齐，不能伪造成功通知。\",\n      \"next_action\": \"记录失败转事故最终结果、实际版本/范围/用户影响及接收人时区时间；引用持续恢复记录，由事故负责人继续恢复，运营不能因发布结案关闭事故。\",\n      \"basis\": \"R01–R21按输入模拟事实独立推导；R22实际工具证据\",\n      \"decided_at\": \"2026-10-15T17:24:26.739492+00:00\"\n    },\n    {\n      \"id\": \"R21\",\n      \"title\": \"文字补充\",\n      \"facts\": \"RC1批准有效，记录仅补充同一监控页面链接，源码/制品/配置/范围/条件/证据均未变，已记录无影响理由。\",\n      \"request\": \"判断是否需要重批或重跑全部验证。\",\n      \"decision\": \"无需重批或重跑全部验证，保留仍有效批准与证据。\",\n      \"rationale\": \"只补同一监控链接且已记录无影响理由，源码/制品/配置/范围/条件/证据未变化，不触发对象漂移。\",\n      \"references\": [\n        \"skills/06-release-and-change-management/release-readiness/SKILL.md\",\n        \"docs/workflows/06-release-and-change-management.md\"\n      ],\n      \"gaps\": \"无场景内缺口；保留补充时间、变更diff与无影响理由。\",\n      \"next_action\": \"按当前有效授权和健康条件继续；后续若相关实质变化再重评受影响范围。\",\n      \"basis\": \"R01–R21按输入模拟事实独立推导；R22实际工具证据\",\n      \"decided_at\": \"2026-10-15T17:24:26.739492+00:00\"\n    },\n    {\n      \"id\": \"R22\",\n      \"title\": \"隔离本地真实执行\",\n      \"facts\": \"仅授权本机临时目录、合成数据、127.0.0.1服务和自身子进程；仓库scripts/local_delivery.py已有固定Git制品、真实服务、失败/恢复及取消能力。禁止真实远端/生产/商店/外发通知。\",\n      \"request\": \"使用阶段06技能在隔离目录实际验证固定制品、同物跨目标、目标应用路径、失败停止恢复，以及中断后的状态核实和安全新执行。保留原始产物/命令/请求/摘要/子进程收口、读资产的轨迹和可复验脚本。你自行设计实际步骤与判据，明确模拟的批准/事件与真正执行，不能把桌面决定或现有测试报告替代实际操作。\",\n      \"decision\": \"限定HTTP本地实测通过；完整本地渠道验收因真实浏览器未执行保持阻塞；不作生产/正式发布结论。\",\n      \"rationale\": \"真实固定提交构建ZIP，两个独立目标消费同一候选ZIP，服务/API/匿名拒绝/HTML真实请求通过，受控503暂停并原旧ZIP恢复；取消后核实并安全新执行，原始结果在r22-actual.json。\",\n      \"references\": [\n        \"skills/06-release-and-change-management/progressive-release-execution/SKILL.md\",\n        \"docs/workflows/06-release-and-change-management.md\"\n      ],\n      \"gaps\": \"真实浏览器五状态/键盘/截图/资源证据未执行；真实商店、生产保护、远端身份、数据库迁移均未覆盖。\",\n      \"next_action\": \"保留自包含证据与恢复脚本。若要完成本地契约的Web验收，在授权隔离浏览器下补真实浏览器路径；其他渠道另取权限并补平台证据。\",\n      \"basis\": \"R01–R21按输入模拟事实独立推导；R22实际工具证据\",\n      \"decided_at\": \"2026-10-15T17:24:26.739492+00:00\"\n    }\n  ],\n  \"actual_r22\": {\n    \"scope\": \"actual loopback only; simulated release decisions\",\n    \"cancel\": {\n      \"state\": \"cancelled\",\n      \"error\": \"controlled cancellation after actual child readiness\"\n    },\n    \"post_cancel\": [\n      {\n        \"ready\": {\n          \"target_id\": \"local-809d44b152584ce389846abbf1917fdf\",\n          \"role\": \"backend\",\n          \"artifact_sha256\": \"ec3aedb5f75325eaf8516e7040d06c1b0b7210d80df3e1c660e532f8c32d59be\",\n          \"source_version\": \"27862eeceb73293f73c815d7dfd0feb793ee9ea2\",\n          \"owner_uid\": 501,\n          \"nonce\": \"915d291aae3c4e629f4f2166da8a2f22\",\n          \"pid\": 84163,\n          \"runtime_sha256\": \"d7e1a7ee4a3608c904154f001494e635491d332726dbc6f706df7dd7dd517b29\",\n          \"port\": 60230,\n          \"host\": \"127.0.0.1\"\n        },\n        \"stopped\": {\n          \"pid\": 84163,\n          \"returncode\": -15,\n          \"stopped_at\": \"2026-10-15T17:21:18.381796+00:00\",\n          \"ownership\": \"only this context's Popen child\"\n        },\n        \"port_closed\": true,\n        \"checked_at\": \"2026-10-15T17:21:18.470687+00:00\"\n      },\n      {\n        \"ready\": {\n          \"target_id\": \"local-809d44b152584ce389846abbf1917fdf\",\n          \"role\": \"backend\",\n          \"artifact_sha256\": \"36193fb181f1ba3083fcfbe1b42cb2c519a388e84d65e136851bf0fae406c453\",\n          \"source_version\": \"ebe6b15cbb52f5d2f098387368148a68b3b1abbc\",\n          \"owner_uid\": 501,\n          \"nonce\": \"c6c157d1bdda46b08fec784955344aea\",\n          \"pid\": 84164,\n          \"runtime_sha256\": \"d7e1a7ee4a3608c904154f001494e635491d332726dbc6f706df7dd7dd517b29\",\n          \"port\": 60243,\n          \"ho