import json
import os
import socket
import urllib.error
import uuid
from pathlib import Path

from scripts import local_delivery as delivery

ROOT = Path("/private/tmp/phase06-independent-replay")
prior = json.loads((ROOT / "local-execution/exercise.json").read_text())
previous, current = prior["artifacts"]
report = {
    "scope": "actual loopback only; simulated release decisions",
    "cancel": {},
    "post_cancel": [],
    "negative": [],
}
try:
    delivery.exercise(ROOT / "cancel-execution", current, previous, cancel_after_ready=True)
except InterruptedError as error:
    report["cancel"] = {"state": "cancelled", "error": str(error)}
else:
    raise AssertionError("controlled cancellation did not interrupt")
for directory in sorted((ROOT / "cancel-execution").glob("*-*")):
    ready_path = directory / "ready.json"
    if not ready_path.exists():
        continue
    ready = json.loads(ready_path.read_text())
    stopped = json.loads((directory / "stopped.json").read_text())
    with socket.socket() as client:
        client.settimeout(1)
        port_closed = client.connect_ex(("127.0.0.1", ready["port"])) != 0
    assert port_closed and stopped["pid"] == ready["pid"]
    report["post_cancel"].append(
        {
            "ready": ready,
            "stopped": stopped,
            "port_closed": port_closed,
            "checked_at": delivery.datetime.now(delivery.UTC).isoformat(),
        }
    )
# New linked execution consumes retained original ZIPs, without rebuild.
report["new_execution"] = delivery.exercise(ROOT / "safe-new-execution", current, previous)
report["new_execution"]["related_execution"] = "cancel-execution"
target = {"target_id": "local-" + uuid.uuid4().hex, "role": "backend", "owner_uid": os.getuid()}
observations = []
with delivery.process(current, target, ROOT / "timeout-negative", health_delay=0.2) as ready:
    try:
        delivery.request(f"http://127.0.0.1:{ready['port']}", "/health", timeout=0.05)
    except (TimeoutError, urllib.error.URLError) as error:
        observations.append(
            {
                "result": "timeout-as-required",
                "error": repr(error),
                "at": delivery.datetime.now(delivery.UTC).isoformat(),
            }
        )
    else:
        raise AssertionError("timeout did not occur")
report["negative"].append(
    {"case": "bounded health timeout", "identity": ready, "observations": observations}
)
try:
    delivery.unpack(Path(current["artifact"]), "0" * 64, ROOT / "rejected-artifact")
except ValueError as error:
    report["negative"].append({"case": "digest mismatch", "result": str(error)})
else:
    raise AssertionError("digest mismatch accepted")
with delivery.target_lock(ROOT / "lock-negative"):
    try:
        with delivery.target_lock(ROOT / "lock-negative"):
            raise AssertionError("duplicate lock accepted")
    except FileExistsError as error:
        report["negative"].append({"case": "concurrent lock", "result": str(error)})
# Every owned service has stopped; inspect each retained endpoint after completion.
report["final_ports"] = []
for path in ROOT.rglob("ready.json"):
    ready = json.loads(path.read_text())
    stopped = json.loads(path.with_name("stopped.json").read_text())
    with socket.socket() as client:
        client.settimeout(1)
        closed = client.connect_ex(("127.0.0.1", ready["port"])) != 0
    assert closed
    report["final_ports"].append(
        {
            "path": str(path.relative_to(ROOT)),
            "pid": ready["pid"],
            "returncode": stopped["returncode"],
            "port_closed": closed,
        }
    )
(ROOT / "r22-actual.json").write_text(json.dumps(report, ensure_ascii=False, indent=2))
print(
    json.dumps(
        {
            "cancel": report["cancel"],
            "post_cancel_count": len(report["post_cancel"]),
            "new_execution": report["new_execution"]["state"],
            "negative": report["negative"],
            "closed_ports": len(report["final_ports"]),
        }
    )
)

